def _fget(name: str) -> List[float]:
    for n, v in FEXP:
        if n == name:
            return v
    raise ValueError("missing " + name)


def _sget(name: str) -> List[str]:
    for n, v in SEXP:
        if n == name:
            return v
    raise ValueError("missing " + name)


def _flat(got) -> List[float]:
    g = List[float]()
    a = np.asarray(got, dtype=float).ravel()
    for i in range(a.shape[0]):
        g.append(float(a[i]))
    return g


def check(name: str, got, rtol: float = 1e-7, atol: float = 1e-15):
    want = _fget(name)
    g = _flat(got)
    ok = len(g) == len(want)
    if ok:
        for i in range(len(want)):
            if np.isnan(want[i]):
                if not np.isnan(g[i]):
                    ok = False
            elif abs(g[i] - want[i]) > atol + rtol * abs(want[i]):
                ok = False
    if not ok:
        print("TEST FAILED:", name, g[:12], want[:12], len(g), len(want))


def checks(name: str, got):
    want = _sget(name)
    g = [str(v) for v in got]
    if g != want:
        print("TEST FAILED:", name, g, want)



def V(x):
    return x.__val__()


def TS(x):
    return x.__val__()


def mk(nch: int, n: int, k: float):
    out = np.empty((nch, n))
    for i in range(nch):
        for j in range(n):
            out[i, j] = np.sin(0.05 * (i + 1) * j + k) + 0.3 * np.cos(0.31 * j * (i + 2) + 0.5 * i) + 0.2 * np.sin(2.0 * j)
    return out


def descs(ps):
    out = []
    for pr in ps:
        out.append(pr['desc'])
    return out


def evars(ps):
    out = []
    for pr in ps:
        out.append(pr['explained_var'])
    return out


sf = 200.0
n = 6000
names = ['Fp1', 'Fz', 'Cz', 'Pz', 'O1', 'O2', 'ECG', 'EOG']
d = mk(8, n, 0.3) * 1e-5
tt = np.arange(n)
beat = np.zeros(n)
blink = np.zeros(n)
for c in range(100, n - 100, 170):
    beat += np.exp(-0.5 * ((tt - c) / 3.0) ** 2)
for c in range(300, n - 300, 900):
    blink += np.exp(-0.5 * ((tt - c) / 15.0) ** 2)
pat = np.array([1.0, 0.5, -0.3, 0.2, 0.8, -0.6])
pat2 = np.array([0.4, 1.0, 0.1, -0.5, 0.3, 0.9])
d[:6] += 4e-5 * np.outer(pat, beat) + 6e-5 * np.outer(pat2, blink)
d[6] = 1e-3 * beat + 1e-6 * mk(1, n, 5.0)[0]
d[7] = 1e-4 * blink + 1e-6 * mk(1, n, 7.0)[0]
raw = mne.io.RawArray(d, mne.create_info(names, sf, ['eeg'] * 6 + ['ecg', 'eog']))
pe, ee = mne.preprocessing.compute_proj_ecg(raw, n_eeg=2, reject=None, ch_name='ECG')
check("ecg_n", [len(pe), len(ee)])
check("ecg_ev", ee[:, 0])
for i, q in enumerate(pe):
    check("ecg_p%d" % i, np.abs(q['data']['data']), 1e-5, 1e-9)
check("ecg_var", evars(pe), 1e-5, 1e-9)
checks("ecg_desc", descs(pe))
po, eo = mne.preprocessing.compute_proj_eog(raw, n_eeg=1, reject=None, average=False)
check("eog_n", [len(po), len(eo)])
check("eog_ev", eo[:, 0])
for i, q in enumerate(po):
    check("eog_p%d" % i, np.abs(q['data']['data']), 1e-5, 1e-9)
checks("eog_desc", descs(po))
